"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/comparison/variants/05-head-to-head";
export interface ArtemisComparisonHeadToHeadProps { className?: string;  }
export function ArtemisComparisonHeadToHead({ className }: ArtemisComparisonHeadToHeadProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useState, type ReactNode } from "react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { CompareSelect, type Plan } from "./05-head-to-head/compare-select";
import { DiffCheckbox } from "./05-head-to-head/diff-checkbox";
type Value = string | boolean;
type Feature = {
    name: string;
    workspace: Value;
    essentials: Value;
    custom: Value;
};
type PlanKey = "essentials" | "custom";
const PLANS: readonly (Plan & {
    key: PlanKey;
})[] = [
    { key: "essentials", name: "Essentials", description: "The basics, ready to go" },
    { key: "custom", name: "Custom stack", description: "Build and maintain your own" },
];
const FEATURES: readonly Feature[] = [
    { name: "Projects", workspace: "Unlimited", essentials: "Up to 10", custom: "Unlimited" },
    { name: "Team members", workspace: "Unlimited", essentials: "Up to 5", custom: "Unlimited" },
    { name: "Shared knowledge base", workspace: true, essentials: false, custom: "Separate tool" },
    { name: "Search across your work", workspace: true, essentials: true, custom: "Manual setup" },
    { name: "Workflow automation", workspace: true, essentials: false, custom: "Manual setup" },
    { name: "Export your data", workspace: true, essentials: true, custom: true },
    { name: "Support", workspace: "Priority", essentials: "Community", custom: "Self-managed" },
];
const TABLE_TRANSITION = { duration: 0.4, ease: ARTEMIS_EASE_OUT };
const CELL_TRANSITION = { duration: 0.18, ease: ARTEMIS_EASE_OUT };
const CELL = "art:break-words art:px-3 art:py-5 art:text-xs art:leading-5 art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:text-sm";
function CellValue({ value }: {
    value: Value;
}): ReactNode {
    if (typeof value === "string")
        return <span>{value}</span>;
    return (<span className="art:inline-flex art:items-center art:gap-2">
      <span className="art:flex art:size-6 art:shrink-0 art:items-center art:justify-center art:rounded-full art:bg-muted art:text-foreground">
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide ${value ? "art:lucide-check" : "art:lucide-minus"} art:size-3.5`} aria-hidden="true">
          <path d={value ? "M20 6 9 17l-5-5" : "M5 12h14"}/>
        </svg>
      </span>
      <span className="art:sr-only art:@min-[640px]/artemis:not-sr-only">{value ? "Included" : "Not included"}</span>
    </span>);
}
function FadeCell({ value }: {
    value: Value;
}) {
    return (<motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={CELL_TRANSITION}>
      <CellValue value={value}/>
    </motion.div>);
}
export default function ComparisonHeadToHead() {
    const [plan, setPlan] = useState(PLANS[0]);
    const [onlyDiffs, setOnlyDiffs] = useState(false);
    const differs = (f: Feature) => f[plan.key] !== f.workspace;
    const diffCount = FEATURES.filter(differs).length;
    const rows = onlyDiffs ? FEATURES.filter(differs) : FEATURES;
    return (<>
      <section className="art:w-full art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
        <div className="art:mx-auto art:max-w-5xl">
          <div className="art:mx-auto art:max-w-2xl art:text-center">
            <p className="art:text-sm art:font-medium art:text-muted-foreground">
              {"Find your fit"}
            </p>
            <h2 className="art:mt-4 art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {"The details make the difference."}
            </h2>
            <p className="art:mt-5 art:text-pretty art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {"Compare the essentials, then focus on what matters to your team."}
            </p>
          </div>
          <div className="art:mt-10 art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
            <div className="art:flex art:flex-wrap art:items-center art:gap-3">
              <span className="art:text-sm art:text-muted-foreground">
                {"Compare "}
                {"Workspace"}
                {" with"}
              </span>
              <CompareSelect plans={PLANS} value={plan} onChange={(next) => setPlan(PLANS.find((p) => p.name === next.name) ?? PLANS[0])}/>
            </div>
            <DiffCheckbox checked={onlyDiffs} onCheckedChange={setOnlyDiffs} label="Only differences"/>
          </div>
          <motion.div className="art:mt-6 art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.15 }} transition={TABLE_TRANSITION}>
            <table className="art:w-full art:table-fixed art:text-left">
              <caption className="art:sr-only">
                {"Workspace"}
                {" compared with "}
                {plan.name}
                {onlyDiffs ? ", differences only" : " "}
              </caption>
              <colgroup>
                <col className="art:w-2/5"/>
                <col className="art:w-[30%]"/>
                <col className="art:w-[30%]"/>
              </colgroup>
              <thead>
                <tr>
                  <th scope="col" className="art:px-4 art:py-7 art:align-bottom art:text-sm art:font-medium art:text-muted-foreground art:@min-[640px]/artemis:px-6">
                    {"What you get"}
                  </th>
                  <th scope="col" className="art:break-words art:px-3 art:py-7 art:align-top art:@min-[640px]/artemis:px-6">
                    <span className="art:block art:text-xl art:font-medium">
                      {"Workspace"}
                    </span>
                    <span className="art:mt-2 art:hidden art:text-xs art:font-normal art:leading-5 art:text-muted-foreground art:@min-[640px]/artemis:block">
                      {"A workspace that grows with you"}
                    </span>
                  </th>
                  <th scope="col" className="art:break-words art:px-3 art:py-7 art:align-top art:@min-[640px]/artemis:px-6">
                    <span className="art:block art:text-xl art:font-medium">
                      {plan.name}
                    </span>
                    <span className="art:mt-2 art:hidden art:text-xs art:font-normal art:leading-5 art:text-muted-foreground art:@min-[640px]/artemis:block">
                      {plan.description}
                    </span>
                  </th>
                </tr>
              </thead>
              <tbody>
                {rows.map((feature) => (<tr key={feature.name} className="art:border-t art:border-border">
                    <th scope="row" className="art:break-words art:px-4 art:py-5 art:text-xs art:font-medium art:leading-5 art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:text-sm">
                      {feature.name}
                    </th>
                    <td className={CELL}>
                      <FadeCell value={feature.workspace}/>
                    </td>
                    <td className={CELL}>
                      <FadeCell key={plan.key} value={feature[plan.key]}/>
                    </td>
                  </tr>))}
              </tbody>
            </table>
          </motion.div>
          <div className="art:mt-5 art:flex art:flex-wrap art:items-start art:justify-between art:gap-3 art:text-xs art:leading-5 art:text-muted-foreground">
            <p className="art:max-w-lg">
              {"Illustrative products and features. Replace with your own comparison data."}
            </p>
            <output>
              {diffCount}
              {" "}
              {diffCount === 1 ? "difference" : "differences"}
              {" across"}
              {" "}
              {FEATURES.length}
              {" "}
              {"features"}
            </output>
          </div>
        </div>
      </section>
    </>);
}

"use client";
// @zeus-internal
import { Listbox, ListboxButton, ListboxOption, ListboxOptions } from "../../../../lib/headless";
export type Plan = {
    name: string;
    description: string;
};
const BUTTON = "art:inline-flex art:min-w-40 art:items-center art:justify-between art:gap-2 art:border art:border-border art:px-3 art:text-left art:font-medium art:text-foreground art:text-sm art:transition-colors art:hover:border-border-strong art:disabled:pointer-events-none art:disabled:opacity-50 art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:data-focus:outline-none art:data-focus:ring-0 art:data-open:ring-0 art:h-10 art:rounded-full art:bg-background art:focus-visible:ring-2 art:focus-visible:ring-ring";
const PANEL = "art:z-[120] art:overflow-hidden art:rounded-2xl art:border art:border-border-strong/50 art:bg-background art:p-1.5 art:backdrop-blur-xl art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:focus-visible:ring-0 art:data-focus:outline-none art:data-focus:ring-0 art:transition art:duration-150 art:ease-out art:data-closed:scale-95 art:data-closed:opacity-0 art:origin-top art:w-[var(--button-width)] art:shadow-none art:max-w-[calc(100vw-1.5rem)]";
const OPTION = "art:group art:flex art:min-h-11 art:cursor-pointer art:items-center art:gap-3 art:rounded-xl art:px-3 art:py-2 art:text-left art:transition-colors art:data-focus:bg-primary/5 art:data-disabled:pointer-events-none art:data-disabled:opacity-50";
export function CompareSelect({ plans, value, onChange, }: {
    plans: readonly Plan[];
    value: Plan;
    onChange: (value: Plan) => void;
}) {
    return (<Listbox as="div" className="art:relative art:inline-block art:text-left" value={value} onChange={onChange} by={(a: Plan, b: Plan) => a.name === b.name}>
      <ListboxButton aria-label="Compare against" className={BUTTON}>
        {({ open }) => (<>
            <span className="art:min-w-0 art:truncate">{value.name}</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-down art:size-4 art:shrink-0 art:text-muted-foreground art:transition-transform${open ? " art:rotate-180" : ""}`} aria-hidden="true">
              <path d="m6 9 6 6 6-6"/>
            </svg>
          </>)}
      </ListboxButton>
      <ListboxOptions anchor={{ to: "bottom start", gap: 8, padding: 12 }} transition className={PANEL}>
        {plans.map((plan) => (<ListboxOption key={plan.name} value={plan} className={OPTION}>
            <span className="art:min-w-0 art:flex-1">
              <span className="art:block art:truncate art:text-sm">{plan.name}</span>
              <span className="art:block art:truncate art:text-muted-foreground art:text-xs">{plan.description}</span>
            </span>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-4 art:shrink-0 art:opacity-0 art:group-data-selected:opacity-100" aria-hidden="true">
              <path d="M20 6 9 17l-5-5"/>
            </svg>
          </ListboxOption>))}
      </ListboxOptions>
    </Listbox>);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion } from "motion/react";
import { useId } from "react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
const CHECK_TRANSITION = { duration: 0.16, ease: ARTEMIS_EASE_OUT };
export function DiffCheckbox({ checked, onCheckedChange, label, }: {
    checked: boolean;
    onCheckedChange: (checked: boolean) => void;
    label: string;
}) {
    const id = useId();
    return (<label htmlFor={id} className="art:inline-flex art:items-center art:gap-3 art:cursor-pointer art:text-sm">
      <motion.button id={id} type="button" role="checkbox" aria-checked={checked} data-state={checked ? "checked" : "unchecked"} tabIndex={0} whileTap={{ scale: 0.92 }} className={artemisCx("art:inline-flex art:h-5 art:w-5 art:shrink-0 art:items-center art:justify-center art:rounded-md art:border-2 art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:disabled:cursor-not-allowed art:disabled:opacity-60", checked
            ? "art:border-primary art:bg-primary art:text-primary-foreground" : "art:border-muted-foreground/50 art:bg-background art:hover:border-muted-foreground")} onClick={() => onCheckedChange(!checked)}>
        <AnimatePresence initial={false}>
          {checked ? (<motion.svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.5, filter: "blur(4px)" }} transition={CHECK_TRANSITION}>
              <title>Selected</title>
              <path d="M5 13l4 4L19 7" pathLength={1} strokeDashoffset="0" strokeDasharray="1 1"/>
            </motion.svg>) : null}
        </AnimatePresence>
      </motion.button>
      <span className="art:select-none art:text-sm art:text-foreground">{label}</span>
    </label>);
}
